#include <bits/stdc++.h>
using namespace std;
using ll = long long;

void solve(){
    int n;
    cin>>n;
    int m = 3*n;
    vector<ll> a(m+1);
    
    for(int i=1;i<m+1;i++){
        cin>>a[i];
    }

    sort(a.begin()+1,a.end(),greater<ll>());
    
    vector<ll> pr(m + 1);
    
    for(int i=1;i<=m;i++){
        pr[i] = pr[i-1] + a[i];
    }
    
    auto g = [&](int x,int y){
        int z = (6*n - 3*x - y) / 2;
        
        return 2LL*pr[x] + pr[y] + 3LL* pr[z];
    };
    
    ll ans = 0;
    
    
    for(int par=0;par<2;par++){
        int x = par;
        int y = 2*n;
        
        if((y-x)%2 != 0){
            y--;
        }
        
        while(x <= n){
            y = min(y,2*n - x);
            
            if(y < x){
                break;
            }
            
            while(y - 2 >= x && g(x,y-2) >= g(x,y)){
                y-=2;
            }
            
            ans = max(ans,g(x,y));
            x+=2;
        }
        
    }    
    
    cout<<ans<<"\n";
}
int main() {
	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	int T;
	cin>>T;
	
	while(T--){
	    solve();
	}

}
